    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_GoDsclInsert_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.goDsclInsert()
        /* sdd-asis-lifecycle:end */

